const raw = $json || {};
const body = raw.body && typeof raw.body === 'object' ? raw.body : {};
const query = raw.query && typeof raw.query === 'object' ? raw.query : {};
const headers = raw.headers && typeof raw.headers === 'object' ? raw.headers : {};
const incoming = { ...raw, ...query, ...body };
const webhookSecret = $env.N8N_WEBHOOK_SECRET || '';
if (!webhookSecret) throw new Error('N8N_WEBHOOK_SECRET is required.');
const receivedSecret = incoming.webhook_secret || headers['x-bakery-webhook-secret'] || headers['X-Bakery-Webhook-Secret'] || '';
if (receivedSecret !== webhookSecret) throw new Error('Unauthorized webhook request.');
const userRequest = String(incoming.user_request || incoming.request || incoming.natural_request || '').trim();
if (!userRequest) throw new Error('user_request is required.');
const imageCount = Number(incoming.image_count || 3);
if (!Number.isInteger(imageCount) || imageCount < 1 || imageCount > 8) throw new Error('image_count must be an integer between 1 and 8.');
const autoApprove = Boolean(incoming.auto_approve);
return [{ json: {
  user_request: userRequest,
  execution_mode: incoming.execution_mode || incoming.mode || 'dry-run',
  platforms: incoming.platforms || incoming.platform || 'xiaohongshu,douyin',
  image_count: imageCount,
  preferred_image_id: incoming.preferred_image_id || 'deconstructed',
  local_demo: incoming.local_demo !== undefined ? Boolean(incoming.local_demo) : true,
  live_image: Boolean(incoming.live_image || incoming.live),
  mock_publish: incoming.mock_publish !== undefined ? Boolean(incoming.mock_publish) : false,
  approval_mode: incoming.approval_mode || (autoApprove ? 'auto' : 'manual'),
  auto_approve: autoApprove,
  approval_note: incoming.approval_note || (autoApprove ? 'Pipeline auto-approved because auto_approve=true was explicitly requested.' : ''),
  image_note: incoming.image_note || 'Pipeline selected preferred image variant.',
  db: incoming.db || incoming.db_path || 'data/agent_ops.sqlite3',
  out_dir: incoming.out_dir || 'runs/operations',
  approval_out_dir: incoming.approval_out_dir || 'runs/approval_queue',
  image_out_dir: incoming.image_out_dir || 'runs/generated_images',
  archive_out_dir: incoming.archive_out_dir || 'runs/operation_archive',
  publish_out_dir: incoming.publish_out_dir || 'runs/publish_drafts',
  log: incoming.log || 'runs/operation_log.jsonl',
  env_file: incoming.env_file || '.env'
} }];
